import java.util.Scanner;

public class Main {
    static long factorial(int n) {
        if(n <= 1) {
            return 1;
        }
        return n * factorial(n - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        System.out.println(factorial(n));
    }
}

import java.util.Scanner;

public class Main {
    static long sumNatural(int n) {
        if(n == 0) {
            return 0;
        }
        return n + sumNatural(n - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        System.out.println(sumNatural(n));
    }
}

import java.util.Scanner;

public class Main {
    static int fib(int n) {
        if(n <= 2) {
            return 1;
        }
        return fib(n - 1) + fib(n - 2);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        System.out.println(fib(n));
    }
}

import java.util.Scanner;

public class Main {
    static long power(int base, int exp) {
        if(exp == 0) {
            return 1;
        }
        return base * power(base, exp - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int base = sc.nextInt();
        int exp = sc.nextInt();
        System.out.println(power(base, exp));
    }
}

import java.util.Scanner;

public class Main {
    static int digitSum(long n) {
        if(n < 10) {
            return (int) n;
        }
        return (int)(n % 10) + digitSum(n / 10);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        System.out.println(digitSum(n));
    }
}

import java.util.Scanner;

public class Main {
    static String reverse(String s) {
        if(s.length() <= 1) {
            return s;
        }
        return reverse(s.substring(1)) + s.charAt(0);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String word = sc.next();
        System.out.println(reverse(word));
    }
}

import java.util.Scanner;

public class Main {
    static void countdown(int n) {
        if(n == 0) {
            System.out.println("Liftoff!");
            return;
        }
        System.out.println(n);
        countdown(n - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        countdown(n);
    }
}

import java.util.Scanner;

public class Main {
    static long sumCalories(int[] values, int index) {
        if(index == values.length) {
            return 0;
        }
        return values[index] + sumCalories(values, index + 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] values = new int[n];
        for(int i = 0; i < n; i++) {
            values[i] = sc.nextInt();
        }
        System.out.println(sumCalories(values, 0));
    }
}

import java.util.Scanner;

public class Main {
    static int ways(int n) {
        if(n == 0 || n == 1) {
            return 1;
        }
        return ways(n - 1) + ways(n - 2);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        System.out.println(ways(n));
    }
}

import java.util.Scanner;

public class Main {
    static void singVerse(int bottles) {
        if(bottles == 0) {
            return;
        }
        if(bottles == 1) {
            System.out.println("1 bottle of juice on the wall");
        } else {
            System.out.println(bottles + " bottles of juice on the wall");
        }
        singVerse(bottles - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        singVerse(n);
    }
}
